<script setup lang="ts">
import { computed, onMounted, onServerPrefetch, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { listGames, ownProfile, searchProfiles } from '../lib/api'
import type { Game, Player } from '../lib/models'
import { useSessionStore } from '../stores/session'
import { configured } from '../lib/supabase'

const session = useSessionStore()
const name = ref(''), games = ref<Game[]>([]), players = ref<Player[]>([])
const selected = ref('all'), sort = ref<'recent' | 'ready'>('recent')
const loading = ref(true), error = ref('')
const featured = computed(() => players.value.filter(p => selected.value === 'all' || p.game_id === selected.value)
  .sort((a, b) => sort.value === 'ready' ? Number(b.ready) - Number(a.ready) || b.updated_at.localeCompare(a.updated_at) : b.updated_at.localeCompare(a.updated_at)).slice(0, 6))
function profilePath(player: Player) { return `/profil/${encodeURIComponent(player.id)}` }
function gameSlug(id: string) { return games.value.find(g => g.id === id)?.slug || '' }
async function load() {
  if (!configured) { loading.value = false; return }
  loading.value = true; error.value = ''
  try {
    const id = session.user?.id
    const [catalog, person] = await Promise.all([listGames(), id ? ownProfile(id) : Promise.resolve(null)])
    name.value = String((person as { display_name?: string } | null)?.display_name || session.user?.user_metadata?.display_name || 'Teman')
    games.value = catalog
    const results = await Promise.allSettled(catalog.map(game => searchProfiles(game.slug)))
    players.value = results.flatMap(result => result.status === 'fulfilled' ? result.value : []).filter(player => player.user_id !== id)
  } catch { error.value = 'Pilihan komunitas belum bisa dimuat. Coba lagi, ya.' }
  finally { loading.value = false }
}
onMounted(load)
onServerPrefetch(load)
</script>

<template>
  <main class="community"><div class="community-inner">
    <section class="hero"><div class="hero-top"><div><p class="hero-label">Temukan teman mainmu</p><h1>Selamat datang kembali, {{ name || 'Teman' }}!</h1><p>Jelajahi profil pemain, cocokkan game dan gaya main, lalu kirim ajakan kalau sudah pas.</p></div><div class="hero-actions"><RouterLink class="primary" to="/pilih-game">Cari Teman Mabar</RouterLink><RouterLink class="secondary" to="/profil-saya#profil-game">Buat Profil Game</RouterLink></div></div><div class="game-filter" role="group" aria-label="Filter game"><button type="button" :aria-pressed="selected === 'all'" @click="selected = 'all'">Semua Game</button><button v-for="game in games" :key="game.id" type="button" :aria-pressed="selected === game.id" @click="selected = game.id">{{ game.name }}</button></div></section>
    <div class="columns"><section aria-labelledby="browse-title"><div class="feed-heading"><div class="feed-title"><span class="feed-icon" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c-5 5-5 13 0 18m0-18c5 5 5 13 0 18"/></svg></span><div><h2 id="browse-title">Jelajah Teman Mabar</h2><p>Belum ada fitur lobi langsung. Kenalan dengan pemain yang siap mabar lewat profil publik.</p></div></div><div class="tabs" role="group" aria-label="Urutkan pemain"><button :aria-pressed="sort === 'recent'" type="button" @click="sort = 'recent'">Terbaru</button><button :aria-pressed="sort === 'ready'" type="button" @click="sort = 'ready'">Siap mabar</button></div></div>
      <p v-if="!configured" class="state" role="alert">Layanan belum dikonfigurasi.</p><p v-else-if="loading" class="state" role="status">Memuat profil komunitas…</p><div v-else-if="error" class="state" role="alert"><p>{{ error }}</p><button type="button" class="secondary" @click="load">Coba lagi</button></div><div v-else-if="!featured.length" class="state"><h3>Belum ada pemain di game ini</h3><p>Coba game lain atau lengkapi profil game kamu dulu.</p><RouterLink class="primary" to="/pilih-game">Pilih Game</RouterLink></div>
      <div v-else class="feed"><article v-for="player in featured" :key="player.id" class="player-card"><header class="player-head"><div class="avatar" aria-hidden="true">{{ player.display_name.charAt(0) }}</div><div><h3>{{ player.display_name }}</h3><p>Profil {{ player.game_name }} <span v-if="player.ready" class="ready">Siap mabar</span></p></div></header><div class="tags"><span class="game-tag">{{ player.game_name }}</span><span v-if="player.rank" class="rank-tag">{{ player.rank }}</span><span v-if="player.role">{{ player.role }}</span><span v-if="player.region">Server {{ player.region }}</span></div><div class="player-foot"><div><strong>Profil pemain</strong><span>Rank dan role diisi pengguna, belum terverifikasi</span></div><RouterLink class="primary" :to="profilePath(player)">Lihat Profil</RouterLink></div></article></div>
      <p v-if="featured.length" class="fine-print">Data profil diisi pengguna, belum terverifikasi. Status siap mabar diatur manual, bukan indikator online.</p><RouterLink v-if="featured.length" class="more-link" :to="selected === 'all' ? '/pilih-game' : `/cari/${encodeURIComponent(gameSlug(selected))}`">Lihat hasil pencarian dan filter</RouterLink>
    </section><aside><div class="widget"><div class="widget-heading"><h2>Teman Sefrekuensi</h2><span>{{ featured.length }} profil ditampilkan</span></div><div v-if="featured.length" class="friend-list"><RouterLink v-for="player in featured.slice(0, 4)" :key="player.id" class="friend" :to="profilePath(player)"><span class="small-avatar" aria-hidden="true">{{ player.display_name.charAt(0) }}</span><span><strong>{{ player.display_name }}</strong><small>{{ player.game_name }}</small></span><span class="friend-action">Lihat</span></RouterLink></div><p v-else>Belum ada profil untuk ditampilkan.</p></div>
      <div class="widget personal"><div class="widget-heading"><h2>Akses Cepat Ruang Pribadi</h2></div><p>Kelola profil game, ajakan, dan preferensi mabar kamu di dashboard pribadi.</p><div class="quick-links"><RouterLink to="/profil-saya#profil-game">Profil game</RouterLink><RouterLink to="/request-mabar">Request mabar</RouterLink></div><RouterLink class="secondary full" to="/beranda">Buka Dashboard Pribadi</RouterLink></div>
      <div class="widget explore"><span class="game-icon" aria-hidden="true">+</span><h2>Belum menemukan teman yang cocok?</h2><p>Pilih game, lalu saring pemain berdasarkan rank, role, region, atau status siap mabar.</p><div class="game-links"><RouterLink v-for="game in games" :key="game.id" :to="`/cari/${encodeURIComponent(game.slug)}`">{{ game.name }}</RouterLink></div><RouterLink class="primary full" to="/pilih-game">Pilih Game</RouterLink></div>
    </aside></div>
  </div></main>
</template>

